parts.text:
{
  "feasible": true,
  "summary": "Se creará la página de contacto `/contacto` con la información de email y teléfono de la empresa, y se añadirá un enlace a la misma en el menú de navegación principal y en las capturas E2E.",
  "assumptions": [
    "La información de contacto utilizada será un email de la empresa (contacto@ejemplo.com) y un teléfono de atención (+34 900 123 456).",
    "La página `/contacto` es una ruta estática dentro de `(crm)` protegida por el AppShell de la aplicación."
  ],
  "tasks": [
    {
      "title": "Añadir enlace de navegación a Contacto",
      "description": "Actualizar `src/components/nav-links.tsx` para incluir el enlace `/contacto` con el texto 'Contacto' y el data-testid `nav-contacto`.",
      "files": [
        "src/components/nav-links.tsx"
      ],
      "references": [
        "src/components/nav-links.tsx"
      ],
      "acceptanceCriteria": [
        {
          "id": "c1",
          "type": "e2e",
          "text": "El menú de navegación principal muestra el enlace a Contacto con data-testid `nav-contacto`."
        }
      ]
    },
    {
      "title": "Crear la página de contacto y registrarla en capturas E2E",
      "description": "Crear la página `src/app/(crm)/contacto/page.tsx` que muestra la información de contacto de la empresa (email, teléfono, horario) usando `PageHeader` y tarjetas estilizadas. Añadir data-testid `contact-page`, `contact-email` y `contact-phone`. Además, registrar la nueva página `/contacto` en `e2e/pages.ts` para que Playwright genere capturas de pantalla.",
      "files": [
        "src/app/(crm)/contacto/page.tsx",
        "e2e/pages.ts"
      ],
      "references": [
        "src/app/(crm)/clientes/page.tsx",
        "src/components/page-header.tsx",
        "e2e/pages.ts"
      ],
      "acceptanceCriteria": [
        {
          "id": "c2",
          "type": "e2e",
          "text": "La página /contacto se renderiza con el título de página en page-title y muestra los campos contact-email y contact-phone."
        },
        {
          "id": "c3",
          "type": "visual",
          "text": "La página de contacto se visualiza correctamente centrada y responsive en las capturas de 1280px y 390px."
        }
      ]
    }
  ]
}
